  if (since >= 0 && since < M.hold) arc = M.strike;
  else if (since >= M.hold && since < M.hold + M.recover) arc = M.strike + (holding ? M.raised - M.strike : M.rest - M.strike) * smooth((since - M.hold) / M.recover);
  else arc = holding ? M.raised : M.rest;
