  const targetZ=.035+wave*(dash?.018:.045)*(1-.35*travel);
  const alpha=1-Math.exp(-12*step);
  s.krakenArmX=(s.krakenArmX||0)+(targetX-(s.krakenArmX||0))*alpha;
  s.krakenArmZ=(s.krakenArmZ||0)+(targetZ-(s.krakenArmZ||0))*alpha;
