      const throwing = state && Number.isFinite(state.throwAt) ? 1 : 0; s.lid = (s.lid ?? 0) + (Math.max(open, throwing) - (s.lid ?? 0)) * Math.min(1, dt * 14);
      g.lid.rotation.x = INKSTRIKE_LID_OPEN * (1 - s.lid); }
  } else if (id === 'superChump') {
