    float cross = (1.0 - smoothstep(0.0, 0.03, min(abs(vUv.x), abs(vUv.y)))) * step(r, 0.3);
    float pulse = (1.0 - smoothstep(0.0, 0.05, abs(r - fract(uTime * 1.3 + seed)))) * 0.45;
