    float ring2 = 1.0 - smoothstep(0.0, 0.015, abs(r - 0.78));
    float marks = step(0.82, r) * step(r, 0.92) * step(0.7, fract(ang / 6.2831853 * 16.0 + uTime * 0.4));
    a = max(max(ring1, ring2 * 0.7), marks * 0.8) * (1.0 - t);
