}`;

// A retained instanced pool. Records: { a: Float32Array(16) attribute values, t, life, follow?(rec,dt)->bool }.
class ShapePool {
  constructor(THREE, name, geometry, cap, attrs, vert, frag, additive, uTime, extra = {}, light = {}) {
    this.cap = cap; this.recs = []; this.attrs = attrs; this._emptyUploaded = false;
    const g = new THREE.InstancedBufferGeometry();
    for (const key of Object.keys(geometry.attributes)) g.setAttribute(key, geometry.attributes[key]);
    if (geometry.index) g.setIndex(geometry.index);
    this.buf = attrs.map(name => { const b = new THREE.InstancedBufferAttribute(new Float32Array(cap * 4), 4).setUsage(THREE.DynamicDrawUsage); g.setAttribute(name, b); return b; });
    g.instanceCount = 1;
    const m = new THREE.ShaderMaterial({ uniforms: { uTime, uAdd: { value: additive ? 1 : 0 }, ...light }, vertexShader: vert, fragmentShader: frag,
      transparent: true, depthWrite: false, side: extra.side ?? THREE.DoubleSide, blending: additive ? THREE.CustomBlending : THREE.NormalBlending });
    if (additive) { m.blendSrc = THREE.OneFactor; m.blendDst = THREE.OneFactor; m.blendSrcAlpha = THREE.ZeroFactor; m.blendDstAlpha = THREE.OneFactor; }
    this.mesh = new THREE.Mesh(g, m); this.mesh.frustumCulled = false; this.mesh.renderOrder = extra.order ?? (additive ? 8 : 5); this.mesh.name = 'special-vfx:' + name;
    geometry.dispose?.();
  }
  _retire(record) {
    if (record.retired) return;
    record.retired = true;
    const finish = record.onEnd; record.onEnd = null;
    if (finish) finish();
  }
  add(life, values, follow = null) {
    if (this.recs.length >= this.cap - 1) this._retire(this.recs.shift());
    const rec = { v: new Float32Array(16), t: 0, life, follow, dead: false };
    rec.v.set(values);
    this.recs.push(rec);
    return rec;
  }
  // Scalar births retain fresh public handles while avoiding the transient values array.
  addRaw(life, a0,a1,a2,a3,a4,a5,a6,a7,a8,a9,a10,a11,a12,a13,a14,a15, follow = null) {
    if (this.recs.length >= this.cap - 1) this._retire(this.recs.shift());
    const rec = { v: new Float32Array(16), t: 0, life, follow, dead: false }, v = rec.v;
    v[0]=a0;v[1]=a1;v[2]=a2;v[3]=a3;v[4]=a4;v[5]=a5;v[6]=a6;v[7]=a7;
    v[8]=a8;v[9]=a9;v[10]=a10;v[11]=a11;v[12]=a12;v[13]=a13;v[14]=a14;v[15]=a15;
    this.recs.push(rec);return rec;
  }
  update(dt) {
    if(this.recs.length===0&&this._emptyUploaded)return;
    // Follow/onEnd callbacks can inspect, clear or append to the live roster.
    // Keep their original reverse-splice semantics; batch only callback-free lists.
    let plain = true;
    for (const r of this.recs) if (r.follow || r.onEnd) { plain = false; break; }
    if (plain) {
      const expired = this._expired ||= [], count = this.recs.length;
      for (let i = count - 1; i >= 0; i--) {
        const r = this.recs[i];r.t += dt;
        expired[i] = r.dead || (r.life > 0 && r.t >= r.life);
        if (expired[i]) this._retire(r);
      }
      let out = 0;
      for (let i = 0; i < count; i++) if (!expired[i]) this.recs[out++] = this.recs[i];
      this.recs.length = out;expired.length = 0;
    } else for (let i = this.recs.length - 1; i >= 0; i--) {
      const r = this.recs[i]; r.t += dt;
      if (r.dead || (r.life > 0 && r.t >= r.life) || (r.follow && r.follow(r, dt) === false)) { this.recs.splice(i, 1); this._retire(r); }
    }
    const n = this.recs.length;
    for (let k = 0; k < this.buf.length; k++) {
      const A = this.buf[k].array;
      let start = Infinity, end = 0;
      for (let c = 0; c < 4; c++) { if (!Object.is(A[c], 0)) { start = Math.min(start, c); end = Math.max(end, c + 1); A[c] = 0; } }
      for (let j = 0; j < n; j++) { const v = this.recs[j].v; const o = (j + 1) * 4, s = k * 4;
        for (let c = 0; c < 4; c++) { if (!Object.is(A[o+c], v[s+c])) { start = Math.min(start, o+c); end = Math.max(end, o+c+1); A[o+c] = v[s+c]; } }
      }
