  if(!family||p.delay>0||p._iwShooterMuzzleSeen||!p.owner?.color||!(p.age>=0&&p.age<4/60)||!p.start)return;
  p._iwShooterMuzzleSeen=true;
  if(camera&&camera.distanceToSquared(p.start)>900)return;
